  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2f3a2c;
  background: #fbfaf6;
}

a {
  color: inherit;
}

/* One content width for the header, hero, and cards, so wide screens keep them together. */
.site-header-inner,
.hero,
.features {
  max-width: 1280px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  border-bottom: 1px solid #e6e3da;
}

.site-header-inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 28px;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 22px;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0 28px;
}

.site-nav a {
  display: inline-block;
  padding: 4px 0;
  text-decoration: none;
  color: #55604f;
  white-space: nowrap;
}

/* The hero uses the same four columns as the cards below, so the plot map lines up with them. */
.hero {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px 12px;
  align-items: center;
  padding-top: 56px;
  padding-bottom: 48px;
}

.hero-text {
  grid-column: 1 / 3;
  max-width: 520px;
}

h1 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.15;
}

.hero-text p {
  margin: 0 0 24px;
  color: #55604f;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #3d6b35;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.hero-plan {
  grid-column: 3 / 5;
  max-width: 460px;
  padding: 20px;
  border: 1px solid #e6e3da;
  border-radius: 8px;
  background: #ffffff;
}

.plan-title {
  margin-bottom: 12px;
  color: #2f3a2c;
  font-weight: 500;
}

.plan-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.plot {
  height: 52px;
  padding: 4px 6px;
  border-radius: 4px;
  font-size: 13px;
}

.plot.taken {
  background: #e4e8df;
  color: #55604f;
}

.plot.free {
  background: #3d6b35;
  color: #ffffff;
}

/* The word "Free" sits on the free plot itself, so the reader does not need the key. */
.plot-state {
  display: block;
}

.plan-key {
  margin-top: 12px;
  font-size: 13px;
  color: #55604f;
}

.swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin: 0 6px 0 0;
  border-radius: 2px;
}

.swatch.taken {
  margin-left: 16px;
  background: #e4e8df;
}

.swatch.free {
  background: #3d6b35;
}

.features {
  padding-top: 8px;
  padding-bottom: 48px;
}

h2 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 22px;
  font-weight: 400;
  color: #2f3a2c;
}

.cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.card {
  padding: 14px 16px;
  background: #f1efe8;
}

.card h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
  color: #2f3a2c;
}

.card p {
  margin: 0;
  color: #55604f;
  /* Avoids a single word alone on the last line, in browsers that support it. */
  text-wrap: pretty;
}

/* Tablet: hero in one column, cards in two. */
@media (max-width: 900px) {
  .site-header-inner,
  .hero,
  .features {
    padding-left: 32px;
    padding-right: 32px;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .hero-text,
  .hero-plan {
    grid-column: auto;
  }

  .hero-plan {
    width: 100%;
    max-width: 460px;
  }

  .cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Phone: nav on its own row, cards in one column. */
@media (max-width: 600px) {
  .site-header-inner,
  .hero,
  .features {
    padding-left: 20px;
    padding-right: 20px;
  }

  .site-header-inner {
    padding-top: 16px;
    padding-bottom: 12px;
  }

  .site-nav {
    width: 100%;
    gap: 0 20px;
  }

  .hero {
    padding-top: 32px;
  }

  .cards {
    grid-template-columns: 1fr;
  }
}

